CREATE TABLE warehouse_shifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,warehouse_id uuid NOT NULL,name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','active','closed')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id));
CREATE TABLE labor_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,warehouse_id uuid NOT NULL,shift_id uuid REFERENCES warehouse_shifts(id) ON DELETE SET NULL,assignee_id uuid REFERENCES users(id) ON DELETE SET NULL,task_type text NOT NULL CHECK(task_type IN('receiving','putaway','replenishment','picking','packing','counting','dock','cross_dock')),task_id uuid NOT NULL,task_reference text NOT NULL,priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('low','normal','high','urgent')),status text NOT NULL DEFAULT 'assigned' CHECK(status IN('assigned','in_progress','paused','blocked','completed','cancelled')),planned_units numeric(18,6),completed_units numeric(18,6) NOT NULL DEFAULT 0,started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id));
CREATE TABLE labor_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES labor_assignments(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('assigned','started','paused','resumed','blocked','completed','reassigned')),reason_code text,note text,occurred_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id));
CREATE INDEX labor_assignments_queue_idx ON labor_assignments(company_id,status,priority,created_at);CREATE INDEX labor_events_assignment_time_idx ON labor_events(company_id,assignment_id,occurred_at);
ALTER TABLE warehouse_shifts ENABLE ROW LEVEL SECURITY;ALTER TABLE warehouse_shifts FORCE ROW LEVEL SECURITY;ALTER TABLE labor_assignments ENABLE ROW LEVEL SECURITY;ALTER TABLE labor_assignments FORCE ROW LEVEL SECURITY;ALTER TABLE labor_events ENABLE ROW LEVEL SECURITY;ALTER TABLE labor_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_warehouse_shifts ON warehouse_shifts USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_labor_assignments ON labor_assignments USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_labor_events ON labor_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON warehouse_shifts,labor_assignments,labor_events TO stockflow_app;
